"use client";

import { useState, useEffect } from "react";
import { useRouter } from "next/navigation";
import { Trash2, Shield, ShieldOff, UserCheck, Search, ShieldAlert } from "lucide-react";

interface UserData {
  user_id: string;
  first_name: string;
  last_name: string;
  email: string;
  role: string;
  created_at: string;
}

export default function AdminUsersPage() {
  const router = useRouter();
  const [users, setUsers] = useState<UserData[]>([]);
  const [loading, setLoading] = useState(true);

  // Взимане на потребителите
  const fetchUsers = async () => {
    try {
      const token = localStorage.getItem("token");
      if (!token) {
        router.push("/login");
        return;
      }

      const res = await fetch("http://localhost:5000/admin/users", {
        headers: { "token": token }
      });

      if (res.ok) {
        const data = await res.json();
        setUsers(data);
      } else {
        // Ако не е админ или има грешка
        router.push("/");
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchUsers();
  }, []);

  // Изтриване на потребител
  const handleDeleteUser = async (id: string) => {
    if (!confirm("ВНИМАНИЕ: Изтриването на потребител е необратимо! Сигурни ли сте?")) return;

    try {
      const token = localStorage.getItem("token");
      const res = await fetch(`http://localhost:5000/admin/users/${id}`, {
        method: "DELETE",
        headers: { "token": token || "" }
      });

      if (res.ok) {
        // Махаме го от екрана веднага, без да презареждаме всичко
        setUsers(users.filter(u => u.user_id !== id));
      } else {
        const msg = await res.json();
        alert(msg);
      }
    } catch (err) {
      console.error(err);
    }
  };

  // Смяна на роля (User <-> Admin)
  const toggleUserRole = async (user: UserData) => {
    const newRole = user.role === 'admin' ? 'user' : 'admin';
    const confirmMsg = user.role === 'admin' 
        ? "Сигурни ли сте, че искате да ПРЕМАХНЕТЕ админ правата на този потребител?" 
        : "Сигурни ли сте, че искате да направите този потребител АДМИНИСТРАТОР?";

    if (!confirm(confirmMsg)) return;

    try {
      const token = localStorage.getItem("token");
      const res = await fetch(`http://localhost:5000/admin/users/${user.user_id}/role`, {
        method: "PUT",
        headers: { "Content-Type": "application/json", "token": token || "" },
        body: JSON.stringify({ role: newRole })
      });

      if (res.ok) {
        // Обновяваме само този потребител в локалния стейт
        setUsers(users.map(u => u.user_id === user.user_id ? { ...u, role: newRole } : u));
      } else {
        const msg = await res.json();
        alert(msg);
      }
    } catch (err) {
      console.error(err);
    }
  };

  if (loading) {
    return (
        <div className="min-h-screen bg-[#0a0a0a] flex items-center justify-center">
            <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-[#ff6b00]"></div>
        </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#0f0f13] text-white p-6 md:p-12 font-sans">
      <div className="max-w-7xl mx-auto">
        
        <div className="flex flex-col md:flex-row justify-between items-end mb-8 border-b border-[#333] pb-6">
            <div>
                <h1 className="text-3xl md:text-4xl font-black text-white uppercase tracking-tighter italic">
                  Управление на <span className="text-[#ff6b00]">Потребители</span>
                </h1>
                <p className="text-gray-400 mt-2 text-sm uppercase tracking-widest">
                    Общо регистрирани: {users.length}
                </p>
            </div>
            
            <div className="bg-[#18181b] p-3 rounded flex items-center gap-2 border border-[#333] mt-4 md:mt-0">
                <Search size={18} className="text-gray-500" />
                <span className="text-xs text-gray-500 font-bold uppercase tracking-widest">Админ Зона</span>
            </div>
        </div>

        <div className="bg-[#18181b] rounded-xl border border-[#333] overflow-hidden shadow-2xl">
            <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                    <thead>
                        <tr className="bg-[#0f0f13] text-gray-500 text-[10px] uppercase font-bold tracking-widest border-b border-[#333]">
                            <th className="p-5">Потребител</th>
                            <th className="p-5">Email</th>
                            <th className="p-5">Роля</th>
                            <th className="p-5">Дата на регистрация</th>
                            <th className="p-5 text-right">Действия</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-[#333]">
                        {users.map((user) => (
                            <tr key={user.user_id} className="hover:bg-[#222] transition-colors group">
                                <td className="p-5 font-bold text-white">
                                    <div className="flex items-center gap-3">
                                        <div className={`p-2 rounded-full ${user.role === 'admin' ? 'bg-[#ff6b00]/20 text-[#ff6b00]' : 'bg-[#333] text-gray-400'}`}>
                                            {user.role === 'admin' ? <ShieldAlert size={16}/> : <UserCheck size={16}/>}
                                        </div>
                                        <div>
                                            {user.first_name} {user.last_name}
                                            {user.role === 'admin' && <span className="ml-2 text-[8px] bg-[#ff6b00] text-black px-1 rounded font-black uppercase">ADMIN</span>}
                                        </div>
                                    </div>
                                </td>
                                <td className="p-5 text-gray-400 text-sm font-mono">{user.email}</td>
                                <td className="p-5">
                                    <span className={`px-3 py-1 rounded text-[10px] font-black uppercase tracking-widest border ${user.role === 'admin' ? 'bg-[#ff6b00]/10 border-[#ff6b00]/30 text-[#ff6b00]' : 'bg-[#333] border-transparent text-gray-400'}`}>
                                        {user.role}
                                    </span>
                                </td>
                                <td className="p-5 text-gray-500 text-xs">
                                    {new Date(user.created_at).toLocaleDateString("bg-BG")}
                                </td>
                                <td className="p-5 text-right">
                                    <div className="flex items-center justify-end gap-2 opacity-100 md:opacity-0 group-hover:opacity-100 transition-opacity">
                                        {/* Бутон за роля */}
                                        <button 
                                            onClick={() => toggleUserRole(user)}
                                            className={`p-2 rounded border transition ${user.role === 'admin' ? 'border-gray-600 text-gray-400 hover:bg-gray-800' : 'border-blue-900/50 text-blue-500 hover:bg-blue-900/20'}`}
                                            title={user.role === 'admin' ? "Премахни права" : "Направи Админ"}
                                        >
                                            {user.role === 'admin' ? <ShieldOff size={16} /> : <Shield size={16} />}
                                        </button>

                                        {/* Бутон за изтриване */}
                                        <button 
                                            onClick={() => handleDeleteUser(user.user_id)}
                                            className="p-2 bg-red-900/10 hover:bg-red-600 hover:text-white text-red-500 rounded border border-red-900/30 transition"
                                            title="Изтрий потребител"
                                        >
                                            <Trash2 size={16} />
                                        </button>
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
                
                {users.length === 0 && (
                    <div className="p-12 text-center text-gray-500 uppercase font-bold tracking-widest">
                        Няма намерени потребители
                    </div>
                )}
            </div>
        </div>

      </div>
    </div>
  );
}